const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches
pres.author = 'WorkspaceX';
pres.title = '团队协作：打造高效协同的团队';

const FONT = '微软雅黑';
const COLOR_PRIMARY = '1F4E79';
const COLOR_ACCENT = '2E75B6';
const COLOR_LIGHT_BG = 'D6E4F0';
const COLOR_WHITE = 'FFFFFF';
const COLOR_DARK_TEXT = '333333';
const COLOR_SUBTITLE = '555555';

// Helper: add consistent footer
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 11.8, y: 7.0, w: 1.2, h: 0.3,
    fontSize: 10, fontFace: FONT, color: '999999', align: 'right'
  });
}

// Helper: section title bar at top
function addTopBar(slide, title) {
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLOR_PRIMARY }
  });
  slide.addText(title, {
    x: 0.6, y: 0.15, w: 12, h: 0.8,
    fontSize: 28, fontFace: FONT, bold: true, color: COLOR_WHITE
  });
}

// ========== Slide 1: Cover ==========
const s1 = pres.addSlide();
s1.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 7.5, fill: { color: COLOR_PRIMARY }
});
s1.addShape(pres.ShapeType.rect, {
  x: 0, y: 5.8, w: 13.33, h: 1.7, fill: { color: COLOR_ACCENT }
});
s1.addText('团队协作', {
  x: 1, y: 1.8, w: 11.33, h: 1.5,
  fontSize: 54, fontFace: FONT, bold: true, color: COLOR_WHITE, align: 'center'
});
s1.addText('打造高效协同的团队', {
  x: 1, y: 3.3, w: 11.33, h: 1.0,
  fontSize: 28, fontFace: FONT, color: COLOR_LIGHT_BG, align: 'center'
});
s1.addText('2024 · 内部培训分享', {
  x: 1, y: 6.0, w: 11.33, h: 0.8,
  fontSize: 18, fontFace: FONT, color: COLOR_WHITE, align: 'center'
});

// ========== Slide 2: Why Teamwork Matters ==========
const s2 = pres.addSlide();
addTopBar(s2, '为什么团队协作至关重要？');
addFooter(s2, 2);

const reasons = [
  { icon: '🎯', title: '提升效率', desc: '合理分工让每个人聚焦擅长领域，减少重复劳动，整体产出提升 30%+' },
  { icon: '💡', title: '激发创新', desc: '多元视角碰撞产生新想法，跨职能协作是创新的最佳催化剂' },
  { icon: '🛡️', title: '降低风险', desc: '互相补位与代码/方案评审，让问题在早期被发现和解决' },
  { icon: '😊', title: '增强归属感', desc: '良好的协作氛围提升员工满意度，降低离职率，留住核心人才' }
];

reasons.forEach((r, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const xBase = 0.6 + col * 6.2;
  const yBase = 1.5 + row * 2.7;

  s2.addShape(pres.ShapeType.roundRect, {
    x: xBase, y: yBase, w: 5.8, h: 2.3,
    fill: { color: COLOR_LIGHT_BG }, rectRadius: 0.15
  });
  s2.addText(r.icon, {
    x: xBase + 0.3, y: yBase + 0.3, w: 0.8, h: 0.8,
    fontSize: 36, align: 'center', valign: 'middle'
  });
  s2.addText(r.title, {
    x: xBase + 1.2, y: yBase + 0.25, w: 4.2, h: 0.6,
    fontSize: 22, fontFace: FONT, bold: true, color: COLOR_PRIMARY
  });
  s2.addText(r.desc, {
    x: xBase + 1.2, y: yBase + 0.9, w: 4.2, h: 1.2,
    fontSize: 14, fontFace: FONT, color: COLOR_DARK_TEXT, lineSpacingMultiple: 1.3
  });
});

// ========== Slide 3: Core Principles ==========
const s3 = pres.addSlide();
addTopBar(s3, '高效团队协作的四大核心原则');
addFooter(s3, 3);

