  { num: '02', title: '信任透明', items: ['信息默认公开，减少信息差', '坦诚反馈，对事不对人', '承认错误，鼓励试错文化'] },
  { num: '03', title: '清晰分工', items: ['RACI矩阵明确权责边界', '每个任务有唯一负责人', '依赖关系提前沟通暴露'] },
  { num: '04', title: '持续改进', items: ['定期回顾（Retrospective）', '量化协作指标并追踪趋势', '小步迭代优化工作流程'] }
];

principles.forEach((p, i) => {
  const xBase = 0.4 + i * 3.2;
  const yBase = 1.5;

  // Number circle
  s3.addShape(pres.ShapeType.ellipse, {
    x: xBase + 1.0, y: yBase, w: 0.9, h: 0.9,
    fill: { color: COLOR_ACCENT }
  });
  s3.addText(p.num, {
    x: xBase + 1.0, y: yBase, w: 0.9, h: 0.9,
    fontSize: 22, fontFace: FONT, bold: true, color: COLOR_WHITE, align: 'center', valign: 'middle'
  });

  // Title
  s3.addText(p.title, {
    x: xBase, y: yBase + 1.1, w: 2.9, h: 0.6,
    fontSize: 20, fontFace: FONT, bold: true, color: COLOR_PRIMARY, align: 'center'
  });

  // Items
  const itemText = p.items.map(item => `• ${item}`).join('\n');
